package com.cryptostrategy.platform.leaderboard.internal;import com.cryptostrategy.platform.leaderboard.api.model.LeaderboardRevision;import java.util.*;public final class LeaderboardReproductionVerifier{public List<String> verify(LeaderboardRevision a,LeaderboardRevision b){List<String>d=new ArrayList<>();if(!a.rankingVersion().equals(b.rankingVersion()))d.add("rankingVersion");if(!a.entries().stream().map(e->e.rank()+"|"+e.evaluationFingerprint()+"|"+e.score()+"|"+e.maximumDrawdown()).toList().equals(b.entries().stream().map(e->e.rank()+"|"+e.evaluationFingerprint()+"|"+e.score()+"|"+e.maximumDrawdown()).toList()))d.add("entries");if(!a.fingerprint().equals(b.fingerprint()))d.add("leaderboardFingerprint");return List.copyOf(d);}}
